 {auto old=juce::JSON::parse(json);for(auto key:{"orbitEnabled","orbitRate","orbitDepth"})old["audio"].getDynamicObject()->removeProperty(key);require(target.importUserPreset(juce::JSON::toString(old),name,error)&&target.param("orbitEnabled")==0&&std::abs(target.param("orbitRate")-.07f)<.001&&std::abs(target.param("orbitDepth")-.7f)<.002,"old complete presets get orbit defaults");old["audio"].getDynamicObject()->setProperty("orbitEnabled",true);require(!target.importUserPreset(juce::JSON::toString(old),name,error),"partial orbit triplet rejected");require(target.importUserPreset(json,name,error),"restore current preset");}invalid(change("audio","orbitRate",.7));invalid(change("audio","orbitEnabled",1));
 for(int mode=0;mode<3;++mode){set(source,"projection",float(mode));set(source,"network",float(mode));set(source,"pulsemode",float(mode));set(source,"scale",float(mode));set(source,"voices",float(mode));set(source,"root",mode?84:24);require(target.importUserPreset(source.exportUserPreset("Boundary"),name,error),"boundary enum/root import");for(auto id:{"projection","network","pulsemode","scale","voices","root"})require(source.param(id)==target.param(id),"enum/root mappings");}
 {auto doc=juce::JSON::parse(json);doc.getDynamicObject()->setProperty("__proto__","ignored");doc["audio"].getDynamicObject()->setProperty("field",true);require(target.importUserPreset(juce::JSON::toString(doc),name,error)&&target.param("field")==0,"unknown keys clean ignored");}
 auto root=juce::File::getCurrentWorkingDirectory();require(root.getChildFile("evidence").createDirectory().wasOk(),"create test evidence directory");auto fixture=root.getChildFile("evidence/user-preset.json");for(auto pair:values)set(source,pair.first,pair.second);require(source.saveUserPresetFile(fixture,"Native Roundtrip",error),"actual native fixture write");require(target.loadUserPresetFile(fixture,name,error),"actual native fixture read");auto tooBig=root.getChildFile("evidence/oversized-preset-test.tmp");require(tooBig.replaceWithText(juce::String::repeatedString("x",262145)),"write oversize fixture");auto intact=target.exportUserPreset("Before");require(!target.loadUserPresetFile(tooBig,name,error)&&intact==target.exportUserPreset("Before"),"oversized file rejects atomically");require(tooBig.deleteFile(),"remove owned temporary fixture");auto browser=root.getSiblingFile("output").getChildFile("browser-user-preset.json");if(browser.existsAsFile()){require(target.loadUserPresetFile(browser,name,error),"actual browser fixture native import");require(target.param("root")==33&&target.param("pulsemode")==2&&target.param("binaural")==1&&std::abs(target.param("reverb")-.45f)<.002,"browser fixture mappings");std::cout<<"PASS browser fixture imported natively\n";}
